// --- Inlined bare-mux transport wrapper (added to the raw epoxy core) --------------------
// Lets the K4q9p2Xv controller use this epoxy build directly, exactly like the L1bc
// transport: init() / meta() / request() / connect(). Mirrors the known-good
// @mercuryworkshop/epoxy-transport wrapper. It reaches the core classes (Ep082Client,
// Ep082ClientOptions, Ep082Handlers) and the wasm init (W, the module's default export)
// directly, since they are declared above in this same module.
//
// This build's Ep082Client.fetch() resolves to a standard web Response (no rawHeaders),
// so response headers are read from res.headers, with getSetCookie() recovering the
// individual Set-Cookie headers a Headers object would otherwise fold into one.
const ep082TransportOpts = [
  'wisp_v2',
  'udp_extension_required',
  'title_case_headers',
  'ws_title_case_headers',
  'wisp_ws_protocols',
  'redirect_limit',
  'header_limit',
  'buffer_size',
];

export class Ep082Transport {
  ready = false;
  client = null;

  constructor(options) {
    this.wisp = options.wisp;
    this.opts = options;
  }

  setopt(options, opt) {
    if (this.opts[opt] != null) options[opt] = this.opts[opt];
  }

  async init() {
    if (this.ready) return; // idempotent: safe whether the controller or caller invokes it
    await W();
    const options = new Ep082ClientOptions();
    options.user_agent = navigator.userAgent;
    ep082TransportOpts.forEach((x) => this.setopt(options, x));
    this.client = new Ep082Client(this.wisp, options);
    this.ready = true;
  }

  async meta() {}

  async request(remote, method, body, headers, signal) {
    if (body instanceof Blob) body = await body.arrayBuffer();

    const headersObj = {};
    for (const [key, value] of headers) headersObj[key] = value;

    const res = await this.client.fetch(remote.href, {
      method,
      body,
      headers: headersObj,
      redirect: 'manual',
    });

    const headersEntries = [];
    res.headers.forEach((value, key) => headersEntries.push([key, value]));
    if (typeof res.headers.getSetCookie === 'function') {
      const cookies = res.headers.getSetCookie();
      if (cookies.length) {
        for (let i = headersEntries.length - 1; i >= 0; i--) {
          if (headersEntries[i][0].toLowerCase() === 'set-cookie') headersEntries.splice(i, 1);
        }
        for (const c of cookies) headersEntries.push(['set-cookie', c]);
      }
    }

    return {
      body: res.body,
      headers: headersEntries,
      status: res.status,
      statusText: res.statusText,
    };
  }

  connect(url, protocols, requestHeaders, onopen, onmessage, onclose, onerror) {
    const handlers = new Ep082Handlers(
      // epoxy does not surface the server-selected protocol/extension
      () => onopen('', ''),
      // epoxy does not surface the close code/reason
      () => onclose(1000, 'Closed by remote'),
      onerror,
      (data) => (data instanceof Uint8Array ? onmessage(data.buffer) : onmessage(data)),
    );

    const headersObj = {};
    for (const [key, value] of requestHeaders) headersObj[key] = value;

    const ws = this.client.connect_websocket(handlers, url.href, protocols, headersObj);
    return [
      async (data) => {
        if (data instanceof Blob) data = await data.arrayBuffer();
        (await ws).send(data);
      },
      async (code, reason) => {
        (await ws).close(code, reason || '');
      },
    ];
  }
}
